def extract_clean_json(content: str) -> str:

    """Finds and extracts the largest valid balanced JSON object string, ignoring braces inside strings."""

    first_brace = content.find('{')

    if first_brace == -1:

        return ""

    

    brace_count = 0

    in_string = False

    escape = False

    

    for i in range(first_brace, len(content)):

        char = content[i]

        

        if escape:

            escape = False

            continue

            

        if char == '\\':

            escape = True

            continue

            

        if char == '"':

            in_string = not in_string

            continue

            

        if not in_string:

            if char == '{':

                brace_count += 1

            elif char == '}':

                brace_count -= 1

                if brace_count == 0:

                    return content[first_brace:i+1]

    return ""

def parse_malformed_tool_calls(content: str) -> List[dict]:

    """

    Parses malformed tool calls from Groq/Llama response content.

    Looks for JSON structures or Markdown code blocks containing JSON tool call requests.

    Returns a list of dicts in the form:

    [{"name": tool_name, "args": tool_args, "id": unique_id}]

    """

    import re

    import json

    import uuid



    if not content or not isinstance(content, str):

        return []



    results = []



    # 1. Look for markdown code blocks containing JSON

    json_blocks = re.findall(r"```(?:json)?\s*(\{.*?\})\s*```", content, re.DOTALL)

    

    # 2. If no code blocks, look for any JSON-like dict in the text using balanced brace extraction

    if not json_blocks:

        extracted = extract_clean_json(content)

        if extracted:

            json_blocks = [extracted]



    for block in json_blocks:

        try:

            data = json.loads(block)

            

            # Handle list of tool calls

            if isinstance(data, list):

                candidates = data

            else:

                candidates = [data]

                

            for item in candidates:

                if not isinstance(item, dict):

                    continue

                

                # Extract tool name

                name = item.get("name") or item.get("tool") or item.get("function")

                if not name or not isinstance(name, str):

                    continue

                    

                # Extract args

                args = item.get("args") or item.get("arguments") or item.get("parameters") or item.get("inputs") or {}

                if not isinstance(args, dict):

                    args = {}

                    

                # Ensure unique ID

                call_id = item.get("id") or item.get("tool_call_id") or f"call_{uuid.uuid4().hex[:8]}"

                

                results.append({

                    "name": name,

                    "args": args,

                    "id": call_id

                })

        except Exception:

            pass



    # 3. Fallback: Parse line-based Action / Action Input or direct function-like calls

    if not results:

        action_match = re.search(r"Action:\s*(\w+)", content, re.IGNORECASE)

        if action_match:

            name = action_match.group(1).strip()

            args = {}

            arg_match = re.search(r"Action Input:\s*(\{.*\})", content, re.DOTALL | re.IGNORECASE)

            if arg_match:

                try:

                    args = json.loads(arg_match.group(1).strip())

                except Exception:

                    pass

            results.append({

                "name": name,

                "args": args,

                "id": f"call_{uuid.uuid4().hex[:8]}"

            })



    return results

def _intelligently_compress_observation(observation: str, target_instruction: str, tool_name: str, tool_args: dict) -> str:
    if not isinstance(observation, str):
        observation = str(observation)
    if len(observation) <= 8000:
        return observation
        
    print(f"[CODING WORKER] Observation from {tool_name} too large ({len(observation)} chars). Running semantic compression...")
    from src.core.compressor import Compressor
    
    # Pre-slice extremely massive outputs to avoid embedding memory crashes
    if len(observation) > 100000:
        observation = observation[:50000] + "\n...[OMITTED MASSIVE MIDDLE]...\n" + observation[-50000:]
        
    query_context = f"Find the results, relevant text, and errors for the tool {tool_name} executing task: {target_instruction}"
    try:
        compressed = Compressor.compress([observation], query=query_context, max_tokens=1500)
        return f"[INTELLIGENTLY COMPRESSED TOOL OUTPUT]\n{compressed}"
    except Exception as e:
        logger.warning(f"Failed to compress observation: {e}")
        # Fallback to hard slice
        return observation[:4000] + "\n... [TRUNCATED DUE TO LENGTH] ...\n" + observation[-4000:]

