def _get_language(language: str):
    """Get the tree-sitter language object for the given language name."""
    if language in _LANGUAGE_MODULES:
        module_name, attr = _LANGUAGE_MODULES[language]
        try:
            mod = __import__(module_name)
            return getattr(mod, attr)()
        except ImportError as e:
            logger.error(f"Tree-sitter {language} language not installed: {e}")
            raise
    raise ValueError(f"Unsupported language: {language}")

def _extract_methods(body_node, source: str) -> List[str]:
    """Extract method names from a class body."""
    methods = []
    for child in body_node.children:
        if child.type in ("function_definition", "async_function_definition"):
            name_node = child.child_by_field_name("name")
            if name_node:
                methods.append(name_node.text.decode("utf-8"))
    return methods

def _extract_arguments(args_node) -> List[Dict[str, Any]]:
    """Extract function arguments with type annotations."""
    arguments = []
    
    for child in args_node.children:
        if child.type == "identifier" or child.type == "typed_parameter":
            # Handle regular parameters
            if child.type == "typed_parameter":
                name_node = child.child_by_field_name("name")
                type_node = child.child_by_field_name("type")
                name = name_node.text.decode("utf-8") if name_node else ""
                arg_type = type_node.text.decode("utf-8") if type_node else ""
            else:
                name = child.text.decode("utf-8") if child.text else ""
                arg_type = ""
            
            if name:
                arguments.append({"name": name, "type": arg_type})
                
    return arguments

def _extract_type_annotation(type_node, content: bytes) -> str:
    """Extract type annotation from a type node."""
    if type_node and type_node.text:
        return type_node.text.decode("utf-8", errors="replace")
    return ""

def _extract_bases(node) -> List[str]:
    """Extract class inheritance bases."""
    bases = []
    
    for child in node.children:
        if child.type == "argument_list":
            for arg in child.children:
                if arg.type not in ("(", ")", ","):
                    bases.append(arg.text.decode("utf-8", errors="replace"))
    return bases

def _find_parent_class(node) -> Optional[str]:
    """Find the parent class name by walking up the tree for Python."""
    
    parent = node.parent
    while parent:
        if parent.type == "class_definition":
            name_node = parent.child_by_field_name("name")
            return name_node.text.decode("utf-8") if name_node else None
        parent = parent.parent
    return None

def _find_js_parent_class(node) -> Optional[str]:
    """Find the parent class name by walking up the tree for JavaScript/TypeScript."""
    
    parent = node.parent
    while parent:
        if parent.type == "class_declaration":
            name_node = parent.child_by_field_name("name")
            return name_node.text.decode("utf-8") if name_node else None
        parent = parent.parent
    return None

def _extract_js_methods(body_node, source: str) -> List[str]:
    """Extract method names from a JavaScript class body."""
    methods = []
    for child in body_node.children:
        if child.type == "method_definition":
            name_node = child.child_by_field_name("name")
            if name_node:
                name = name_node.text.decode("utf-8")
                if name != "constructor":
                    methods.append(name)
    return methods

def _extract_js_arguments(args_node) -> List[Dict[str, Any]]:
    """Extract function arguments for JavaScript/TypeScript."""
    arguments = []
    
    for child in args_node.children:
        if child.type == "identifier" or child.type == "formal_parameters":
            # Handle regular parameters
            if child.type == "identifier":
                name = child.text.decode("utf-8") if child.text else ""
                if name:
                    arguments.append({"name": name, "type": ""})
        elif child.type == "comment":
            continue
                
    return arguments

def _extract_imports(node, imports: List[Dict[str, Any]], filepath: str, content: bytes, language: str = "python") -> None:
    """Extract import statements from tree-sitter node."""
    
    if language in ("javascript", "jsx", "typescript", "tsx"):
        # JavaScript/TypeScript import: import ... from 'module'
        if node.type == "import_statement":
            source_node = None
            import_clause = None
            
            for child in node.children:
                if child.type == "string":
                    source_node = child
                elif child.type == "import_clause":
                    import_clause = child
            
            if import_clause:
                for child in import_clause.children:
                    if child.type == "identifier":
                        name = child.text.decode("utf-8") if child.text else ""
                        imports.append({
                            "type": "import",
                            "name": name,
                            "module": source_node.text.decode("utf-8").strip("'\"") if source_node else "",
                            "line": node.start_point[0] + 1,
                            "filepath": filepath,
                        })
                    elif child.type == "named_imports":
                        for named in child.children:
                            if named.type == "import_specifier":
                                name_node = named.child_by_field_name("name")
                                if name_node:
                                    imports.append({
                                        "type": "import",
                                        "name": name_node.text.decode("utf-8"),
                                        "module": source_node.text.decode("utf-8").strip("'\"") if source_node else "",
                                        "line": node.start_point[0] + 1,
                                        "filepath": filepath,
                                    })
        
        # JavaScript require() calls
        elif node.type == "call":
            func_node = node.child_by_field_name("function")
            if func_node and func_node.type == "identifier" and func_node.text.decode("utf-8") == "require":
                args = node.child_by_field_name("arguments")
                if args and args.children:
                    for arg in args.children:
                        if arg.type == "string":
                            module = arg.text.decode("utf-8").strip("'\"")
                            imports.append({
                                "type": "require",
                                "name": module,
                                "module": module,
                                "line": node.start_point[0] + 1,
                                "filepath": filepath,
                            })
    else:
        # Python imports (default behavior)
        if node.type == "import_statement":
            import_nodes = []
            for child in node.children:
                if child.type == "dotted_name":
                    names = [n.text.decode("utf-8") for n in child.children if n.type not in (",",)]
                    if names:
                        import_nodes.append(names)
                elif child.type == "identifier":
                    import_nodes.append([child.text.decode("utf-8")])
            
            for name_list in import_nodes:
                module_name = ".".join(name_list)
                imports.append({
                    "type": "import",
                    "name": module_name,
                    "asname": None,
                    "line": node.start_point[0] + 1,
                    "filepath": filepath,
                })
                
        elif node.type == "import_from_statement":
            dotted_names = []
            for child in node.children:
                if child.type == "dotted_name":
                    names = [n.text.decode("utf-8") for n in child.children if n.type not in (",",)]
                    dotted_names.append(names[0] if names else "")
            
            module_name = dotted_names[0] if len(dotted_names) > 0 else ""
            
            for name in dotted_names[1:]:
                imports.append({
                    "type": "import_from",
                    "module": module_name,
                    "name": name,
                    "asname": None,
                    "line": node.start_point[0] + 1,
                    "filepath": filepath,
                })
        
    for child in node.children:
        _extract_imports(child, imports, filepath, content, language)

def _extract_calls(node, calls: List[Dict[str, Any]], filepath: str, content: bytes, language: str = "python") -> None:
    """Extract function call expressions from tree-sitter node."""
    
    if node.type == "call":
        func_node = node.child_by_field_name("function")
        
        call_name = ""
        if func_node:
            if func_node.type == "identifier":
                call_name = func_node.text.decode("utf-8")
            elif func_node.type == "member_expression":
                # Handle method calls like obj.method in JS
                obj_node = func_node.child_by_field_name("object")
                prop_node = func_node.child_by_field_name("property")
                obj_name = obj_node.text.decode("utf-8") if obj_node else ""
                prop_name = prop_node.text.decode("utf-8") if prop_node else ""
                if obj_name and prop_name:
                    call_name = f"{obj_name}.{prop_name}"
            elif func_node.type == "attribute":
                # Handle method calls like obj.method() in Python
                obj_node = func_node.child_by_field_name("object")
                attr_node = func_node.child_by_field_name("attribute")
                obj_name = obj_node.text.decode("utf-8") if obj_node else ""
                attr_name = attr_node.text.decode("utf-8") if attr_node else ""
                if obj_name and attr_name:
                    call_name = f"{obj_name}.{attr_name}"
                    
        if call_name:
            calls.append({
                "name": call_name,
                "line": node.start_point[0] + 1,
                "filepath": filepath,
            })
            
    for child in node.children:
        _extract_calls(child, calls, filepath, content, language)

def parse_code_file(filepath: str, language: str = "python") -> Dict[str, Any]:
    """
    Parse a source file using Tree-sitter and extract structured metadata.
    Returns a dictionary compatible with the original AST parser output format.
    Enforces strict language safety: if tree-sitter fails for any reason,
    raises ParserInitializationException.
    """
    logger.info(f"Parsing {language} source file: {filepath}")
    try:
        with open(filepath, "rb") as f:
            content = f.read()

        result = _parse_with_tree_sitter(content, filepath, language)
        return result
    except ImportError as e:
        raise ParserInitializationException(
            f"Tree-sitter language module for '{language}' not installed: {e}"
        ) from e
    except ParserInitializationException:
        raise
    except Exception as e:
        raise ParserInitializationException(
            f"Failed to parse file '{filepath}' with language '{language}': {e}"
        ) from e

def get_symbol_tokens(symbol: dict) -> int:
    """Return the pre‑computed token estimate for a symbol dictionary.
    If not present, fall back to a line‑based estimate.
    """
    est = symbol.get("token_estimate")
    if est is not None:
        return est
    start = symbol.get("start_line")
    end = symbol.get("end_line")
    if start is None or end is None:
        return 0
    return (end - start + 1) * TOKENS_PER_LINE

