def all_tasks_complete(plan: List[PlanTask]) -> bool:
    if not plan:
        return False
    return all(task.status in {"done", "validated"} for task in plan)

def summarize_plan(plan: List[PlanTask]) -> str:
    if not plan:
        return "No plan exists yet."
    lines = []
    for task in plan:
        lines.append(
            f"- {task.id} | {task.status} | {task.title}"
            + (f" | assigned={task.assigned_agent}" if task.assigned_agent else "")
            + (f" | attempts={task.attempt_count}" if task.attempt_count else "")
        )
    return "\n".join(lines)

def extract_validation_status(messages: List[Any]) -> Optional[str]:
    if not messages:
        return None

    last = messages[-1]
    if not isinstance(last, AIMessage) or last.name != "code_critic_worker":
        return None

    content = (last.content or "").lower()
    if "verification failed repeatedly" in content:
        return "failed_repeatedly"
    if "validated" in content or "✓ validated" in content or "status: validated" in content:
        return "validated"
    if "needs changes" in content or "not validated" in content or "failed" in content:
        return "needs_changes"
    return None

def apply_post_worker_state_updates(state: dict, plan: List[PlanTask], messages: list) -> tuple[List[PlanTask], str, list, list]:
    """Deterministic state transitions based on worker completion flags."""
    worker_outputs = state.get("worker_outputs", {})
    worker_complete = state.get("worker_complete", {})
    current_task_id = state.get("current_task_id")
    last_validated_task_id = state.get("last_validated_task_id", "")
    task_history = state.get("task_history") or []
    task_events = state.get("task_events") or []

    if not current_task_id:
        return plan, last_validated_task_id, task_history, task_events

    selected_task = get_task_by_id(plan, current_task_id)
    if not selected_task:
        return plan, last_validated_task_id, task_history, task_events

    if selected_task.status == "needs_replan":
        return plan, last_validated_task_id, task_history, task_events

    worker_type = state.get("worker_type", "")
    is_complete = worker_complete.get(worker_type, False)

    if is_complete and worker_type in {"frontend_worker", "backend_worker", "code_critic_worker", "rag_worker", "web_worker", "utility_worker", "scraper_worker"}:
        if worker_type == "code_critic_worker":
            # Critic decides if it's validated
            critic_feedback = state.get("critic_feedback", {})
            if critic_feedback.get("status") == "validated":
                selected_task.status = "validated"
                last_validated_task_id = current_task_id
                selected_task.evidence.append({
                    "timestamp": datetime.now(timezone.utc).isoformat(),
                    "type": "critic_validation",
                    "worker": "code_critic_worker",
                    "summary": critic_feedback.get("feedback", "")
                })
            elif critic_feedback.get("status") == "needs_changes":
                pass
        else:
            # Coding/utility workers finish their part
            if selected_task.validation_required and worker_type in {"frontend_worker", "backend_worker"}:
                selected_task.status = "in_progress" # Waiting for critic
            else:
                selected_task.status = "done"

            output_summary = str(worker_outputs.get(worker_type, ""))[:500]
            selected_task.last_result_summary = output_summary

            selected_task.evidence.append({
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "type": "worker_completion",
                "worker": worker_type,
                "summary": output_summary
            })

            task_history.append({
                "task_id": selected_task.id,
                "worker": worker_type,
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "status": selected_task.status,
                "summary": output_summary
            })

    return plan, last_validated_task_id, task_history, task_events

async def supervisor_node(state: dict) -> dict:
    messages = state.get("messages", [])
    steps = state.get("steps_remaining", 30)
    retry_counter = int(state.get("retry_counter") or 0)
    active_documents = state.get("active_documents") or []
    cursor_position = state.get("cursor_position") or {}

    ide_context = (
        f"\n[IDE CONTEXT]\nActive Documents: {active_documents}\nCursor: {cursor_position}\n"
        if (active_documents or cursor_position)
        else ""
    )

    plan = normalize_plan(state.get("plan") or [])
    plan, last_validated_task_id, task_history, task_events = apply_post_worker_state_updates(state, plan, messages)

    is_goal_completed = state.get("project_context", {}).get("is_goal_completed", False)
    all_completed = all(t.status in {"done", "validated"} for t in plan) if plan else False

    routing_prompt = [
        SystemMessage(content=SUPERVISOR_PROMPT + ide_context),
        SystemMessage(
            content=(
                f"Task Status Snapshot:\n{summarize_plan(plan)}\n\n"
                f"Steps Remaining: {steps}\n"
                f"Retry Counter: {retry_counter}\n"
                f"Current Task ID: {state.get('current_task_id')}\n"
                f"Last Validated Task ID: {last_validated_task_id}"
            )
        ),
    ]

    messages_to_route = messages
    if len(messages) > MAX_GLOBAL_MESSAGES:
        start_idx = len(messages) - MAX_GLOBAL_MESSAGES
        while start_idx > 0 and isinstance(messages[start_idx], ToolMessage):
            start_idx -= 1
        messages_to_route = messages[start_idx:]
        routing_prompt.append(
            SystemMessage(
                content=(
                    "[SYSTEM NOTE] Older global execution history has been truncated to preserve token limits. "
                    "Rely on the structured Task Status Snapshot above instead of reconstructing completed work from old messages."
                )
            )
        )

    for msg in messages_to_route:
        if isinstance(msg, AIMessage) and msg.name and msg.name != "supervisor":
            routing_prompt.append(HumanMessage(content=f"[{msg.name.upper()}]:\n{msg.content}"))
        else:
            routing_prompt.append(msg)

    if messages_to_route and not isinstance(routing_prompt[-1], HumanMessage):
        routing_prompt.append(HumanMessage(content="Please review the recent outputs and determine the next step."))

    new_steps = max(0, steps - 1)
    next_agent = "synthesizer"
    current_task = ""
    parallel_tasks: List[str] = []
    active_project_override = None
    legacy_plan_output: Optional[List[str]] = None
    current_task_id = state.get("current_task_id")

    try:
        review_status = (state.get("critic_feedback") or {}).get("status")
        review_target = (state.get("critic_feedback") or {}).get("target_worker")

        if state.get("coding_worker_resume_tool_result"):
            next_agent = state.get("worker_type") or "frontend_worker"
            return {
                "next_agent": next_agent,
                "current_task": state.get("current_task", ""),
                "current_task_id": current_task_id,
            }

        if is_goal_completed:
            next_agent = "synthesizer"
        elif not plan and next_agent != "architect_worker":
            next_agent = "architect_worker"
            current_task_id = None
            current_task = "Create the initial architecture blueprint and task plan."
        elif all_completed and not is_goal_completed:
            next_agent = "architect_worker"
            current_task_id = None
            current_task = "Iteratively plan the next tasks for the user's overarching goal."
        elif any(task.status == "needs_replan" for task in plan):
            next_agent = "architect_worker"
            current_task_id = None
            current_task = "Replan tasks that exhausted their retry budget."
        elif review_status == "needs_changes" and review_target in {"frontend_worker", "backend_worker"}:
            selected_task = get_task_by_id(plan, state.get("current_task_id"))
            next_agent = review_target
            if selected_task:
                if selected_task.attempt_count >= selected_task.max_attempts:
                    logger.warning(f"Task {selected_task.id} failed repeatedly (attempts: {selected_task.attempt_count}). Escalating.")
                    selected_task.status = "needs_replan"
                    next_agent = "architect_worker"
                    current_task_id = None
                    current_task = "Replan tasks that exhausted their retry budget."
                else:
                    current_task_id = selected_task.id
                    selected_task.status = "in_progress"
                    selected_task.assigned_agent = next_agent
                    selected_task.attempt_count += 1
                    task_events.append({"event": "task_retry_started", "task": selected_task.id})
                    current_task = build_task_instruction(selected_task, "")
            return {
                "next_agent": next_agent,
                "current_task": current_task,
                "current_task_id": current_task_id,
                "plan": serialize_plan(plan),
                "task_events": task_events,
            }
        elif all_tasks_complete(plan):
            next_agent = "synthesizer"
        else:
            model = get_routing_model()
            for attempt in range(3):
                try:
                    response = await model.ainvoke(routing_prompt)
                    break
                except Exception as e:
                    if attempt == 2:
                        raise e
                    logger.warning(f"Supervisor LLM parsing failed (attempt {attempt+1}): {e}")
                    routing_prompt.append(HumanMessage(content=f"Failed to parse structured output. Error: {e}\nPlease correct your JSON and try again."))

            next_agent = response.next_agent
            parallel_tasks = getattr(response, "parallel_tasks", []) or []
            active_project_override = getattr(response, "active_project", None) or None
            if active_project_override == "":
                active_project_override = None

            # Handle parallel routing branch
            if next_agent == "parallel":
                processed_parallel_tasks = []
                for p_route in parallel_tasks:
                    task = get_task_by_id(plan, p_route.task_id)
                    if task and task.status in {"pending", "in_progress"}:
                        task.status = "in_progress"
                        task.assigned_agent = p_route.agent
                        task.attempt_count += 1
                        task_events.append({"event": "task_started", "task": task.id})
                        processed_parallel_tasks.append({"agent": p_route.agent, "task_id": task.id})

                if processed_parallel_tasks:
                    parallel_tasks = processed_parallel_tasks
                    selected_task = None
                    current_task_id = None
                    current_task = "Executing tasks in parallel."
                else:
                    next_agent = "synthesizer"

            if next_agent != "parallel":
                selected_task = get_task_by_id(plan, response.current_task_id)

                if selected_task is None and next_agent != "synthesizer":
                    selected_task = get_next_pending_task(plan)

            if selected_task and selected_task.domain == "integration" and next_agent in {"frontend_worker", "backend_worker"}:
                next_agent = "backend_worker"

            if selected_task and selected_task.status in {"done", "validated", "blocked", "cancelled"}:
                logger.warning(
                    "Supervisor selected a completed or blocked task (%s). Overriding to next pending task.",
                    selected_task.id
                )
                selected_task = get_next_pending_task([t for t in plan if t.id != selected_task.id])

            if (
                next_agent in {"frontend_worker", "backend_worker"}
                and selected_task
                and selected_task.id == last_validated_task_id
            ):
                logger.warning(
                    "Supervisor attempted to reroute a validated task (%s) back to frontend/backend worker. Overriding.",
                    selected_task.id
                )
                selected_task = get_next_pending_task([t for t in plan if t.id != selected_task.id])
                if not selected_task:
                    next_agent = "synthesizer"

            if messages and isinstance(messages[-1], AIMessage):
                last_agent = messages[-1].name
                if last_agent == next_agent and next_agent not in ["frontend_worker", "backend_worker", "synthesizer"]:
                    logger.warning(f"Supervisor loop detected: {next_agent} called twice.")
                    selected_task = get_next_pending_task(plan)
                    if selected_task:
                        next_agent = "frontend_worker" if selected_task.domain == "frontend" else "backend_worker"
                    else:
                        next_agent = "synthesizer"

            if next_agent == "synthesizer" and not all_tasks_complete(plan):
                logger.warning("Supervisor attempted to exit to synthesizer with pending tasks. Overriding.")
                selected_task = get_next_pending_task(plan)
                if selected_task:
                    next_agent = "frontend_worker" if selected_task.domain == "frontend" else "backend_worker"

            if next_agent != "synthesizer" and selected_task is None:
                selected_task = get_next_pending_task(plan)
                if selected_task is None:
                    next_agent = "synthesizer"
                elif next_agent not in ["frontend_worker", "backend_worker"]:
                    next_agent = "frontend_worker" if selected_task.domain == "frontend" else "backend_worker"

            if selected_task and next_agent != "synthesizer":
                current_task_id = selected_task.id
                selected_task.status = "in_progress"
                selected_task.assigned_agent = next_agent
                selected_task.attempt_count += 1
                task_events.append({"event": "task_started", "task": selected_task.id})
                current_task = (
                    response.current_task
                    if legacy_plan_output is not None and response.current_task
                    else build_task_instruction(selected_task, response.current_task or "")
                )
            else:
                current_task_id = None
                current_task = response.current_task or ""

    except Exception as e:
        logger.error(f"Supervisor routing error: {e}")
        next_agent = "synthesizer"

    valid_agents = [
        "rag_worker", "web_worker", "utility_worker", "scraper_worker",
        "critic_worker", "report_worker", "frontend_worker", "backend_worker", "code_critic_worker",
        "architect_worker", "synthesizer", "parallel", "FINISH",
    ]
    if next_agent not in valid_agents or next_agent == "FINISH":
        next_agent = "synthesizer"

    state_update = {
        "plan": serialize_plan(plan),
        "next_agent": next_agent,
        "current_task": current_task,
        "current_task_id": current_task_id if next_agent != "synthesizer" else None,
        "last_validated_task_id": last_validated_task_id,
        "parallel_tasks": parallel_tasks if next_agent == "parallel" else [],
        "active_project": active_project_override if active_project_override is not None else (state.get("active_project") or None),
        "steps_remaining": new_steps,
        "retry_counter": retry_counter,
        "task_history": task_history,
        "task_events": task_events,
    }

    print(
        f"\n[SUPERVISOR] Next Node: '{next_agent}' | Task ID: '{state_update['current_task_id']}' "
        f"| Task: '{current_task}' | Swarm Tasks: {len(state_update['parallel_tasks'])} | Steps Left: {new_steps}"
    )
    return state_update

def get_reasoning_model():
    """Get the configured LLM model for synthesis."""
    provider = resolve_provider("synthesizer", "primary")
    if provider == "cerebras":
        keys = ("CEREBRAS_API_KEY",)
    elif provider == "mistral":
        keys = ("MISTRAL_API_KEY",)
    else:
        keys = ("AGENT_API_KEY",)
    return build_model_with_fallback(
        "synthesizer",
        SYNTHESIZER_MODEL_PRIMARY,
        SYNTHESIZER_MODEL_FALLBACK,
        temperature=0.3,
        api_key_envs=keys,
    )

async def synthesizer_node(state: dict) -> dict:
    """
    Synthesizes the final response using the original query and accumulated scratchpad findings.
    Checks if all planned tasks are complete before finishing.
    """
    logger.info("Synthesizer node executing...")
    
    messages = state.get("messages", [])
    scratchpad = state.get("scratchpad", "")
    scratchpad_references = state.get("scratchpad_references", [])
    if scratchpad_references:
        scratchpad = "\n".join(scratchpad_references)
        
    plan = state.get("plan", [])
    worker_complete = state.get("worker_complete", {})
    
    # Filter worker messages out of the chat history
    worker_names = {"rag_worker", "web_worker", "utility_worker", "scraper_worker", "critic_worker", "code_critic_worker"}
    clean_messages = []
    for msg in messages:
        if isinstance(msg, dict):
            if msg.get("name") in worker_names:
                continue
            clean_messages.append(msg)
        else:
            if hasattr(msg, "name") and msg.name in worker_names:
                continue
            clean_messages.append(msg)
            
    # Retrieve original user query from messages (in reverse to get the latest intent)
    original_query = ""
    last_human_idx = -1
    for i, msg in enumerate(clean_messages):
        if isinstance(msg, dict):
            if msg.get("role") == "user":
                last_human_idx = i
        elif hasattr(msg, "content") and (msg.__class__.__name__ == "HumanMessage" or getattr(msg, "type", "") == "human"):
            last_human_idx = i

    if last_human_idx != -1:
        msg = clean_messages[last_human_idx]
        original_query = msg.get("content", "") if isinstance(msg, dict) else msg.content
    elif clean_messages:
        last_msg = clean_messages[-1]
        original_query = last_msg.get("content", "") if isinstance(last_msg, dict) else getattr(last_msg, "content", "")

    # Format previous conversation history (excluding the current user query)
    chat_history_parts = []
    for idx, msg in enumerate(clean_messages):
        if idx == last_human_idx:
            continue
        
        role = ""
        content = ""
        if isinstance(msg, dict):
            role = msg.get("role")
            content = msg.get("content", "")
        else:
            content = msg.content
            if msg.__class__.__name__ == "HumanMessage" or getattr(msg, "type", "") == "human":
                role = "user"
            elif msg.__class__.__name__ == "AIMessage" or getattr(msg, "type", "") == "ai":
                role = "assistant"
        
        if role and content:
            chat_history_parts.append(f"[{role}]: {content}")
            
    chat_history_str = "\n".join(chat_history_parts) if chat_history_parts else "(No previous messages)"
        
    synthesis_prompt = f"""You are an expert assistant. Your job is to construct a direct, coherent, and comprehensive response to the user's original query by synthesizing the findings gathered by your specialized team of workers, taking into account the conversation history.

Conversation History:
{chat_history_str}

User Original Query:
"{original_query}"

Accumulated Cooperative Findings:
{scratchpad if scratchpad else "(No findings retrieved)"}

Formatting Guidelines:
1. Provide a direct and structured response answering the query.
2. Use markdown formatting (headers, lists, bold text) for clarity.
3. If findings are missing or contradictory, resolve them logically or state the missing details clearly.
4. Do NOT mention the internal team, 'scratchpad', 'workers', or 'agents' in the final response. Present the answer as a unified response from a single assistant.
5. IMPORTANT: If the task involved creating, writing, or editing files in the workspace (such as HTML, CSS, JS, Python or JSON file operations), do NOT output any file summaries, long code listings, explanations, or next steps. Instead, return a minimal, single-sentence response confirming the action, e.g., 'The file [filename] was successfully created/modified and stored in the workspace directory.'
"""

    model = get_reasoning_model()
    try:
        response = await model.ainvoke([
            SystemMessage(content="You are a helpful AI assistant synthesizing information."),
            HumanMessage(content=synthesis_prompt)
        ])
        final_answer = message_text(response).strip()
    except Exception as e:
        error_str = str(e)
        logger.error(f"Error in synthesizer node: {error_str}")
        # Surface auth errors clearly to the user
        if "401" in error_str or "invalid_api_key" in error_str.lower() or "Invalid API Key" in error_str:
            final_answer = "⚠️ **System Error: LLM API Authentication Failed**\n\nThe AI service returned an authentication error. This usually means the API key has expired or was changed after the server started.\n\n**To fix this:**\n1. Verify your API keys in the `.env` file are valid\n2. Restart the server so it loads the updated keys\n\nTechnical detail: " + error_str[:200]
        elif "429" in error_str or "rate_limit" in error_str.lower():
            final_answer = "⚠️ **Rate Limit Exceeded**\n\nThe AI service is temporarily rate-limited. Please wait a moment and try again."
        elif scratchpad and "[SYSTEM ERROR]" in scratchpad:
            final_answer = f"⚠️ **System Error**\n\nThe pipeline encountered errors during processing:\n\n{scratchpad}"
        else:
            final_answer = f"⚠️ **Error generating response**\n\nHere are the raw findings gathered:\n\n{scratchpad}" if scratchpad else "⚠️ An internal error occurred. Please try again."
        
    try:
        print(f"\n[SYNTHESIZER] Compiled final answer: {final_answer[:60]}...")
    except Exception:
        try:
            safe_print = final_answer[:60].encode('ascii', errors='replace').decode('ascii')
            print(f"\n[SYNTHESIZER] Compiled final answer: {safe_print}...")
        except Exception:
            pass
    return {
        "messages": [AIMessage(content=final_answer)],
        "final_answer": final_answer,
        "worker_complete": worker_complete,
        "next_agent": "FINISH"
    }

def route_based_on_next_agent(state: dict) -> Union[str, List[Send]]:

    if state.get("waiting_for_approval"):
        logger.info("Workflow paused: pending human approval for file operation.")
        return END

    next_agent = state.get("next_agent", "FINISH")
    steps = state.get("steps_remaining", 0)
    if steps <= 0:
        logger.warning("Max recursion steps reached, ending workflow.")
        return END
    if next_agent == "FINISH":
        return END
    elif next_agent == "rag_worker":
        return "rag_worker_node"
    elif next_agent == "web_worker":
        return "web_worker_node"
    elif next_agent == "utility_worker":
        return "utility_worker_node"
    elif next_agent == "scraper_worker":
        return "scraper_worker_node"
    elif next_agent == "critic_worker":
        return "critic_worker_node"
    elif next_agent == "report_worker":
        return "report_worker_node"
    elif next_agent == "frontend_worker":
        return "frontend_worker_node"
    elif next_agent == "backend_worker":
        return "backend_worker_node"
    elif next_agent == "code_critic_worker":
        return "code_critic_worker_node"
    elif next_agent == "architect_worker":
        return "architect_worker_node"
    elif next_agent == "synthesizer":
        return "synthesizer_node"
    elif next_agent == "parallel":
        sends = []
        node_map = {
            "frontend_worker": "frontend_worker_node",
            "backend_worker": "backend_worker_node",
            "rag_worker": "rag_worker_node",
            "web_worker": "web_worker_node",
            "utility_worker": "utility_worker_node",
            "scraper_worker": "scraper_worker_node",
            "critic_worker": "critic_worker_node",
            "report_worker": "report_worker_node",
            "code_critic_worker": "code_critic_worker_node",
            "architect_worker": "architect_worker_node",
            "synthesizer": "synthesizer_node"
        }
        for task in state.get("parallel_tasks", []):
            agent = task.get("agent")
            task_id = task.get("task_id")
            if agent in node_map:
                sends.append(Send(node_map[agent], {"current_task_id": task_id, "worker_type": agent}))
        return sends if sends else END
    return END

def route_after_coding_worker(state: dict) -> str:
    if state.get("waiting_for_approval"):
        return "supervisor_node"
    return "code_critic_worker_node"

def route_after_aggregation(state: dict) -> str:
        next_agt = state.get("next_agent", "supervisor")
        if next_agt == "frontend_worker":
            return "frontend_worker_node"
        elif next_agt == "backend_worker":
            return "backend_worker_node"
        return "supervisor_node"

def get_graph_config(thread_id: str = "default"):
    safe_thread_id = "".join(c for c in thread_id if c.isalnum() or c in "-_")[:100]
    return {"configurable": {"thread_id": safe_thread_id}}

def set_active_project(project_name: str) -> None:
    """Sets the active project subdirectory name to programmatically restrict file writes."""
    active_project_var.set(project_name)

def _is_safe_path(filepath: str) -> bool:
    if not filepath or not filepath.strip():
        return False
        
    norm_path = filepath.replace("\\", "/")
    forbidden_prefixes = ("/", "/etc", "/root", "/usr", "/var", "..")
    if any(norm_path.startswith(p) for p in forbidden_prefixes) or "../" in norm_path:
        return False
        
    _active_project = active_project_var.get()
    if _active_project:
        clean_path = norm_path
        while clean_path.startswith("./"):
            clean_path = clean_path[2:]
        if clean_path.startswith("workspace/"):
            clean_path = clean_path[len("workspace/"):]
        while clean_path.startswith("./"):
            clean_path = clean_path[2:]
            
        allowed_root_configs = {"vite.config.js", "package.json", ".", ""}
        if clean_path not in allowed_root_configs:
            if not (clean_path == _active_project or clean_path.startswith(_active_project + "/") or clean_path.startswith(_active_project + "_")):
                return False
        
    real_workspace = os.path.realpath(WORKSPACE_ROOT)
    abs_path = os.path.realpath(os.path.join(WORKSPACE_ROOT, filepath))
    
    if not abs_path.lower().startswith(real_workspace.lower()):
        return False
            
    rel_path = os.path.relpath(abs_path, WORKSPACE_ROOT)
    normalized_rel = rel_path.replace("\\", "/").lower()
    
    if normalized_rel == ".." or normalized_rel.startswith("../") or ".." in normalized_rel:
        return False
        
    abs_path_norm = abs_path.replace("\\", "/").lower()
    system_forbidden = ["/etc", "/root", "/usr", "/var"]
    for sys_p in system_forbidden:
        if abs_path_norm == sys_p or abs_path_norm.startswith(sys_p + "/"):
            return False
            
    if re.match(r"^[a-zA-Z]:/(etc|root|usr|var)(/|$)", abs_path_norm):
        return False
        
    return True

def _has_allowed_extension(filepath: str) -> bool:
    """Check if the file has an approved extension."""
    return True

def _get_absolute_path(filepath: str) -> str:
    """Get absolute path to a file in the `./workspace` folder."""
    p = filepath.replace("\\", "/")
    
    # Strip leading slashes to prevent os.path.join from treating it as a drive-absolute path on Windows
    while p.startswith("/"):
        p = p[1:]
        
    while p.startswith("./"):
        p = p[2:]
    if p.startswith("workspace/"):
        p = p[len("workspace/"):]
    while p.startswith("./"):
        p = p[2:]
    return os.path.realpath(os.path.join(WORKSPACE_ROOT, os.path.normpath(p)))

def view_code_file(filepath: str, start_line: int = 1, end_line: int = 100) -> str:
    """Safely view a range of lines inside a file in `./workspace`."""
    if not _is_safe_path(filepath):
        return f"Error: Access denied. Filepath '{filepath}' violates safety or path policies."
        
    if not _has_allowed_extension(filepath):
        return f"Error: Access denied. File extension not allowed. Approved extensions: {', '.join(ALLOWED_EXTENSIONS)}"
    
    abs_path = _get_absolute_path(filepath)
    if not os.path.isfile(abs_path):
        return f"Error: File '{filepath}' does not exist."
    
    try:
        with open(abs_path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.readlines()
        
        total_lines = len(lines)
        start_idx = max(0, start_line - 1)
        end_idx = min(total_lines, end_line)
        
        output = []
        for i in range(start_idx, end_idx):
            output.append(f"{i + 1}: {lines[i]}")
            
        header = f"--- Viewing {filepath} (Lines {start_line}-{end_line} of {total_lines}) ---\n"
        return sanitize_file_content_for_llm(header + "".join(output))
    except Exception as e:
        return f"Error reading file '{filepath}': {e}"

def read_files(filepath: str, start_line: int = 1, end_line: int = 100) -> str:
    """Safely view a range of lines inside a file in `./workspace`."""
    return view_code_file(filepath, start_line, end_line)

def search_code(query: str, directory: str = ".") -> str:
    """Find occurrences of a text query inside source code files in `./workspace`."""
    if not _is_safe_path(directory):
        return "Error: Access denied. Target directory violates safety policies."
    
    abs_dir = _get_absolute_path(directory)
    if not os.path.isdir(abs_dir):
        return f"Error: Directory '{directory}' does not exist."
    
    results = []
    max_matches = 50
    matches_count = 0
    
    try:
        for root, dirs, files in os.walk(abs_dir):
            dirs[:] = [d for d in dirs if d not in {".git", "__pycache__", ".venv", "node_modules", "checkpoints"}]
            
            for file in files:
                if not _has_allowed_extension(file):
                    continue
                
                full_path = os.path.join(root, file)
                rel_path = os.path.relpath(full_path, WORKSPACE_ROOT)
                
                if not _is_safe_path(rel_path):
                    continue
                    
                with open(full_path, "r", encoding="utf-8", errors="replace") as f:
                    for line_num, line in enumerate(f, 1):
                        if query in line:
                            results.append(f"{rel_path}:{line_num}: {line.strip()}")
                            matches_count += 1
                            if matches_count >= max_matches:
                                break
                    if matches_count >= max_matches:
                        break
        
        if not results:
            return f"No matches found for '{query}'."
            
        header = f"--- Search results for '{query}' (Max {max_matches} matches) ---\n"
        return sanitize_file_content_for_llm(header + "\n".join(results))
    except Exception as e:
        return f"Error searching code: {e}"

def create_files(filepath: str, content: str) -> str:
    """Create a new file with the specified content inside `./workspace`. Fails if the file already exists."""
    from src.core.code.validation import validate_syntax
    
    if not _is_safe_path(filepath):
        return f"Error: Access denied. Filepath '{filepath}' violates safety or path policies."
        
    if not _has_allowed_extension(filepath):
        return f"Error: Access denied. File extension not allowed. Approved extensions: {', '.join(ALLOWED_EXTENSIONS)}"
        
    abs_path = _get_absolute_path(filepath)
    if os.path.exists(abs_path):
        return f"Error: File '{filepath}' already exists. Use modify_files to make changes."
        
    dir_name = os.path.dirname(abs_path)
    if not os.path.isdir(dir_name):
        try:
            os.makedirs(dir_name, exist_ok=True)
        except Exception as e:
            return f"Error creating parent directory: {e}"
            
    filename = os.path.basename(filepath)
    if filename.lower().endswith((".py", ".js", ".jsx", ".ts", ".tsx")):
        ok, msg = validate_syntax(content, filepath)
        if not ok:
            return f"Error: {msg}"
            
    try:
        with open(abs_path, "w", encoding="utf-8") as f:
            f.write(content)
        return f"Success: Created new file '{filepath}'."
    except Exception as e:
        return f"Error creating file '{filepath}': {e}"

def try_fuzzy_replace(content: str, target: str, replacement: str) -> Optional[str]:
    """Attempts to replace the target block of code in the content using normalized matches."""
    target_norm = target.replace("\r\n", "\n").rstrip()
    content_norm = content.replace("\r\n", "\n")
    
    if target_norm in content_norm:
        if content_norm.count(target_norm) == 1:
            parts = content_norm.split(target_norm, 1)
            return parts[0] + replacement + parts[1]

    target_lines = [line.strip() for line in target.replace("\r\n", "\n").split("\n")]
    if not target_lines or (len(target_lines) == 1 and not target_lines[0]):
        return None
        
    content_lines = [line.replace("\r\n", "\n") for line in content.split("\n")]
    content_lines_stripped = [line.strip() for line in content_lines]
    
    target_len = len(target_lines)
    match_index = -1
    match_count = 0
    
    for i in range(len(content_lines_stripped) - target_len + 1):
        sub_window = content_lines_stripped[i : i + target_len]
        if sub_window == target_lines:
            match_count += 1
            match_index = i
            
    if match_count == 1:
        before = content_lines[:match_index]
        after = content_lines[match_index + target_len :]
        return "\n".join(before + [replacement] + after)
        
    return None

def edit_code_file(filepath: str, target: str, replacement: str) -> str:
    """Search and replace a specific block of text in a file inside `./workspace`. Creates file if missing."""
    from src.tools.rollback import backup_file
    
    if not _is_safe_path(filepath):
        return f"Error: Access denied. Filepath '{filepath}' violates safety or path policies."
        
    if not _has_allowed_extension(filepath):
        return f"Error: Access denied. File extension not allowed. Approved extensions: {', '.join(ALLOWED_EXTENSIONS)}"
        
    abs_path = _get_absolute_path(filepath)
    
    if not os.path.isfile(abs_path):
        dir_name = os.path.dirname(abs_path)
        if not os.path.isdir(dir_name):
            try:
                os.makedirs(dir_name, exist_ok=True)
            except Exception as e:
                return f"Error creating parent directory: {e}"
        try:
            with open(abs_path, "w", encoding="utf-8") as f:
                f.write(replacement)
            return f"Success: Created new file '{filepath}'."
        except Exception as e:
            return f"Error creating file '{filepath}': {e}"
    
    if not target:
        backup_file(filepath)
        from src.core.code.validation import validate_syntax
        if filepath.lower().endswith((".py", ".js", ".jsx", ".ts", ".tsx")):
            ok, msg = validate_syntax(replacement, filepath)
            if not ok:
                return f"Error: Validation failed on overwritten file. {msg}"
        try:
            with open(abs_path, "w", encoding="utf-8") as f:
                f.write(replacement)
            return f"Success: Overwrote '{filepath}' completely."
        except Exception as e:
            return f"Error overwriting file '{filepath}': {e}"

    try:
        with open(abs_path, "r", encoding="utf-8") as f:
            content = f.read()
            
        occurrences = content.count(target)
        if occurrences == 0:
            fuzzy_content = try_fuzzy_replace(content, target, replacement)
            if fuzzy_content is not None:
                backup_file(filepath)
                from src.core.code.validation import validate_syntax
                if filepath.lower().endswith((".py", ".js", ".jsx", ".ts", ".tsx")):
                    ok, msg = validate_syntax(fuzzy_content, filepath)
                    if not ok:
                        return f"Error: Validation failed on fuzzy edited file. {msg}"
                with open(abs_path, "w", encoding="utf-8") as f:
                    f.write(fuzzy_content)
                return f"Success: Modified '{filepath}' successfully using relaxed matching."
                
            return (
                f"Error: Target text not found in '{filepath}'. "
                "Make sure spacing, newlines, and indentation match exactly.\n"
                "Fuzzy matching also failed.\n"
                "Fallback: If you cannot match the exact surgical block, you can overwrite the entire file "
                "by passing an empty target string (target='') and providing the complete new file content in replacement."
            )
        if occurrences > 1:
            return (
                f"Error: Target text matches {occurrences} times in '{filepath}'. "
                "Provide a larger context block to make the target query unique."
            )
            
        backup_file(filepath)
        new_content = content.replace(target, replacement, 1)
        
        from src.core.code.validation import validate_syntax
        if filepath.lower().endswith((".py", ".js", ".jsx", ".ts", ".tsx")):
            ok, msg = validate_syntax(new_content, filepath)
            if not ok:
                return f"Error: Validation failed on edited file. {msg}"
                
        with open(abs_path, "w", encoding="utf-8") as f:
            f.write(new_content)
            
        return f"Success: Modified '{filepath}' successfully."
    except Exception as e:
        return f"Error editing file '{filepath}': {e}"

def modify_files(filepath: str, target_code: str, replacement_code: str) -> str:
    """Search and replace a specific block of text in a file inside `./workspace`. Fails if file does not exist."""
    from src.tools.rollback import backup_file
    
    if not _is_safe_path(filepath):
        return f"Error: Access denied. Filepath '{filepath}' violates safety or path policies."
        
    if not _has_allowed_extension(filepath):
        return f"Error: Access denied. File extension not allowed. Approved extensions: {', '.join(ALLOWED_EXTENSIONS)}"
        
    abs_path = _get_absolute_path(filepath)
    if not os.path.isfile(abs_path):
        return f"Error: File '{filepath}' does not exist. Use create_files to create it first."
        
    if not target_code:
        backup_file(filepath)
        try:
            with open(abs_path, "w", encoding="utf-8") as f:
                f.write(replacement_code)
            return f"Success: Overwrote '{filepath}' completely."
        except Exception as e:
            return f"Error overwriting file '{filepath}': {e}"

    try:
        with open(abs_path, "r", encoding="utf-8") as f:
            content = f.read()
            
        occurrences = content.count(target_code)
        if occurrences == 0:
            fuzzy_content = try_fuzzy_replace(content, target_code, replacement_code)
            if fuzzy_content is not None:
                backup_file(filepath)
                with open(abs_path, "w", encoding="utf-8") as f:
                    f.write(fuzzy_content)
                return f"Success: Modified '{filepath}' successfully using relaxed matching."
                
            return (
                f"Error: Target text not found in '{filepath}'. "
                "Make sure spacing, newlines, and indentation match exactly.\n"
                "Fuzzy matching also failed.\n"
                "Fallback: If you cannot match the exact surgical block, you can overwrite the entire file "
                "by passing an empty target string (target_code='') and providing the complete new file content in replacement_code."
            )
        if occurrences > 1:
            return (
                f"Error: Target text matches {occurrences} times in '{filepath}'. "
                "Provide a larger context block to make the target query unique."
            )
            
        backup_file(filepath)
        new_content = content.replace(target_code, replacement_code, 1)
        with open(abs_path, "w", encoding="utf-8") as f:
            f.write(new_content)
            
        return f"Success: Modified '{filepath}' successfully."
    except Exception as e:
        return f"Error editing file '{filepath}': {e}"

